"use client";

import { forwardRef } from "react";
import { Button, type ButtonProps } from "../button/button";
import { interactiveHoverButtonDefaults, type InteractiveHoverButtonSpecProps } from "../generated/interactive-hover-button.types";
import { cx } from "../utils/cx";
import { ArrowRightIcon } from "../utils/icons";

export interface InteractiveHoverButtonProps
  extends InteractiveHoverButtonSpecProps,
    Omit<ButtonProps, keyof InteractiveHoverButtonSpecProps> {}

/**
 * A button whose label slides away to an arrow (and an optional second label) on hover and keyboard focus.
 * Builds on Button. The second layer is decoration: the accessible name is always the main label.
 */
export const InteractiveHoverButton = forwardRef<HTMLButtonElement, InteractiveHoverButtonProps>(function InteractiveHoverButton(
  {
    children,
    hoverLabel,
    variant = interactiveHoverButtonDefaults.variant,
    size = interactiveHoverButtonDefaults.size,
    className,
    ...rest
  },
  ref,
) {
  return (
    <Button {...rest} ref={ref} variant={variant} size={size} className={cx("rdm-ihb relative overflow-hidden", className)}>
      <span className="rdm-ihb-label">{children}</span>
      <span aria-hidden="true" className="rdm-ihb-hover">
        {hoverLabel}
        <ArrowRightIcon className="size-4 shrink-0 rtl:-scale-x-100" />
      </span>
    </Button>
  );
});

// Generated by rdloom codegen from specs/interactive-hover-button.spec.json (v0.1.0).
// Do not edit. Change the spec and run `npm run gen`.

import type { ReactNode } from "react";

export const interactiveHoverButtonVariantValues = ["primary", "secondary", "ghost", "danger"] as const;
export const interactiveHoverButtonSizeValues = ["sm", "md", "lg"] as const;

/** A button whose label slides away to an arrow, or to a second label with an arrow, on hover and keyboard focus. Builds on Button. */
export interface InteractiveHoverButtonSpecProps {
  /**
   * Button label. This is the accessible name.
   */
  children: ReactNode;
  /**
   * Optional wording shown on hover and focus, next to the arrow. It is visual only and should say the same thing as the label. Without it only the arrow appears.
   */
  hoverLabel?: string;
  /**
   * Visual emphasis, as on Button.
   * @default "primary"
   */
  variant?: "primary" | "secondary" | "ghost" | "danger";
  /**
   * Height, padding and font size, as on Button.
   * @default "md"
   */
  size?: "sm" | "md" | "lg";
  /**
   * Prevents interaction, dims the button and turns the effect off.
   * @default false
   */
  isDisabled?: boolean;
  /**
   * Shows a spinner and blocks presses; the pending state is announced.
   * @default false
   */
  isLoading?: boolean;
  /**
   * Called when the button is pressed by mouse, touch or keyboard.
   */
  onPress?: () => void;
}

export const interactiveHoverButtonDefaults = {
  variant: "primary",
  size: "md",
  isDisabled: false,
  isLoading: false,
} as const;

export const interactiveHoverButtonMeta = {
  "name": "InteractiveHoverButton",
  "version": "0.1.0",
  "status": "experimental",
  "role": "button"
} as const;
